/* ═══════════════════════════════════════════════════════════
   TWINTHOS — WORLD-CLASS DESIGN SYSTEM
   Mirofish-grade. Black #000. White type. One signal green.
   Every pixel earns its place. No cards, no pills, no SaaS patterns.
   ═══════════════════════════════════════════════════════════ */

:root {
  --bg: #000000;
  --text: #FFFFFF;
  --signal: #20F782;
  --signal-dim: rgba(32,247,130,0.12);
  --text-dim: #8A8A8A;
  --text-faint: #555555;
  --border: rgba(255,255,255,0.08);
  --border-strong: rgba(255,255,255,0.15);

  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --speed: 200ms;
  --speed-slow: 400ms;
  --speed-slower: 600ms;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;
  --space-9: 80px;
  --space-10: 120px;

  --container: 1400px;
}

/* ── Reset ── */
*,*::before,*::after { box-sizing: border-box; margin: 0; padding: 0; }
html { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
body {
  font-family: 'Inter', system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
  min-height: 100vh;
}
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }
img, svg { display: block; max-width: 100%; }
ul, ol { list-style: none; }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 3px; }
::selection { background: var(--signal); color: var(--bg); }
:focus-visible { outline: 2px solid var(--signal); outline-offset: 3px; }
.skip-link {
  position: absolute; top: -100%; left: var(--space-4); z-index: 200;
  font-size: 13px; padding: 8px 16px; background: var(--text); color: var(--bg);
  transition: top var(--speed) var(--ease);
}
.skip-link:focus { top: var(--space-3); }

/* ── Container ── */
.container { max-width: var(--container); margin: 0 auto; padding: 0 var(--space-8); }

/* ═══════════════════════════════════════════════════════════
   NAVIGATION
   ═══════════════════════════════════════════════════════════ */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  padding: var(--space-4) var(--space-8);
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: background var(--speed-slow) var(--ease);
}
.nav.scrolled {
  background: rgba(0,0,0,0.92);
}
.nav-inner {
  max-width: var(--container); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; gap: var(--space-6);
}
.nav-brand { flex-shrink: 0; display: flex; align-items: center; }
.nav-brand svg { height: 28px; width: auto; }
.nav-links { display: flex; align-items: center; gap: var(--space-6); }
.nav-link {
  font-size: 13px; font-weight: 500; letter-spacing: -0.01em;
  color: var(--text-dim); transition: color var(--speed);
}
.nav-link:hover { color: var(--text); }
.nav-cta {
  font-size: 13px; font-weight: 600; letter-spacing: -0.01em;
  color: var(--bg); background: var(--signal); padding: 10px 24px;
  transition: background var(--speed), transform var(--speed);
}
.nav-cta:hover { background: #1ae075; color: var(--bg); }
.nav-burger { display: none; }

@media (max-width: 768px) {
  .nav { padding: var(--space-3) var(--space-4); }
  .nav-links { display: none; }
  .nav-burger { display: flex; flex-direction: column; gap: 5px; padding: 4px; cursor: pointer; }
  .nav-burger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 1px; }
  .nav-cta { font-size: 12px; padding: 8px 16px; }
}

/* ═══════════════════════════════════════════════════════════
   LOGO SYSTEM
   Mirofish-grade mark + wordmark lockup.
   Black background, white geometry, single signal dot.
   No gradients. No metal. Intentional geometry.
   ═══════════════════════════════════════════════════════════ */

.logo-mark {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}
.logo-mark svg {
  height: 32px;
  width: auto;
  flex-shrink: 0;
}
.logo-wordmark {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text);
  white-space: nowrap;
  line-height: 1;
}
@media (max-width: 480px) {
  .logo-wordmark { display: none; }
}

/* ═══════════════════════════════════════════════════════════
   HERO — Mirofish Principle 1: ONE BIG IDEA FIRST
   ═══════════════════════════════════════════════════════════ */
.hero {
  position: relative; min-height: 100vh;
  display: flex; align-items: center;
  padding: var(--space-10) var(--space-8);
  overflow: hidden;
}
.hero-inner {
  max-width: var(--container); margin: 0 auto; width: 100%;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--space-8);
  align-items: center;
}
.hero-content { max-width: 780px; }
.hero-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.hero-headline {
  font-size: clamp(64px, 9vw, 110px);
  font-weight: 300;
  line-height: 1.0;
  letter-spacing: -0.035em;
  color: var(--text);
  margin-bottom: var(--space-5);
}
.hero-headline .word {
  display: inline-block;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity var(--speed-slower) var(--ease), transform var(--speed-slower) var(--ease);
}
.hero-headline .word.in { opacity: 1; transform: translateY(0); }
.hero-body {
  font-size: 20px; font-weight: 400; line-height: 1.6;
  letter-spacing: 0.01em; color: var(--text-dim); max-width: 44ch;
}
.hero-cta {
  display: inline-block; margin-top: var(--space-7);
  font-size: 15px; font-weight: 600; letter-spacing: -0.01em;
  color: var(--bg); background: var(--signal);
  padding: 18px 32px;
  transition: background var(--speed), transform var(--speed);
  border: none; cursor: pointer;
}
.hero-cta:hover { background: #1ae075; color: var(--bg); transform: translateY(-1px); }
.hero-secondary {
  display: inline-block; margin-top: var(--space-4);
  font-size: 14px; font-weight: 400; color: var(--text-faint);
}
.hero-brand-col { flex: 0 0 auto; width: clamp(280px, 22vw, 420px); opacity: 0.92; }
.hero-brand-col svg { width: 100%; height: auto; }

@media (max-width: 900px) {
  .hero { padding: var(--space-8) var(--space-5); min-height: auto; }
  .hero-inner { grid-template-columns: 1fr; gap: var(--space-6); }
  .hero-brand-col { width: 200px; order: -1; }
}
@media (max-width: 480px) {
  .hero { padding: var(--space-6) var(--space-4); }
  .hero-headline { font-size: clamp(48px, 12vw, 64px); }
  .hero-body { font-size: 16px; }
  .hero-cta { width: 100%; justify-content: center; padding: 16px 20px; }
}

/* ═══════════════════════════════════════════════════════════
   STORY
   ═══════════════════════════════════════════════════════════ */
.story { padding: var(--space-10) 0; }
.story-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-8);
  align-items: start;
}
.story-text { max-width: 50ch; }
.story-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.story-headline {
  font-size: clamp(48px, 6vw, 72px);
  font-weight: 300; line-height: 1.05; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-6); max-width: 60ch;
}
.story-body {
  font-size: 20px; font-weight: 400; line-height: 1.6;
  letter-spacing: 0.01em; color: var(--text); margin-bottom: var(--space-5);
}
.story-stat {
  padding: var(--space-7) var(--space-6);
  border: 1px solid var(--border);
  background: #0a0a0a;
  display: flex; flex-direction: column; gap: var(--space-4);
}
.story-stat-number {
  font-size: 56px; font-weight: 300; line-height: 1.0; letter-spacing: -0.03em;
}
.story-stat-label {
  font-size: 13px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--text-dim);
}
@media (max-width: 768px) {
  .story-grid { grid-template-columns: 1fr; gap: var(--space-5); }
  .story { padding: var(--space-8) 0; }
}

/* ═══════════════════════════════════════════════════════════
   ENEMY — Mirofish Principle 3: VISUAL METAPHOR
   ═══════════════════════════════════════════════════════════ */
.enemy { padding: var(--space-10) 0; }
.enemy-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.enemy-headline {
  font-size: clamp(48px, 6vw, 72px);
  font-weight: 300; line-height: 1.05; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-8); max-width: 65ch;
}
.enemy-chaos {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
  margin-top: var(--space-7);
  align-items: start;
  perspective: 1200px;
}
.drag-card {
  position: relative;
  padding: var(--space-5) var(--space-4);
  background: #0a0a0a;
  border: 1px solid var(--border);
  min-height: 130px;
  display: flex; flex-direction: column; gap: var(--space-3);
  transform-origin: center center;
  transition: transform var(--speed-slow) var(--ease), box-shadow var(--speed-slow) var(--ease), border-color var(--speed-slow) var(--ease), z-index var(--speed-slow) var(--ease);
  cursor: default;
}
.drag-card:hover {
  transform: translateY(-4px) scale(1.02) rotate(0deg);
  border-color: var(--border-strong);
  box-shadow: 0 20px 50px rgba(0,0,0,0.5);
  z-index: 30;
}
.card-tape {
  position: absolute; top: -7px; left: 50%; transform: translateX(-50%);
  width: 44px; height: 14px;
  background: rgba(255,255,255,0.1);
  border-radius: 1px;
  opacity: 0.5;
}
.card-tape--side {
  top: 22px; left: -8px; width: 16px; height: 34px; transform: none;
}
.card-tape--top { top: -9px; width: 52px; }
.card-body {
  display: flex; flex-direction: column; gap: var(--space-2); position: relative; z-index: 1;
}
.card-icon { color: var(--text-faint); display: flex; align-items: center; }
.card-icon svg { width: 22px; height: 22px; }
.card-label {
  font-size: 18px; font-weight: 600; letter-spacing: -0.01em; color: var(--text);
}
.card-sub {
  font-size: 13px; font-weight: 400; color: var(--text-dim);
  line-height: 1.4; letter-spacing: 0.01em;
}
.card-body--wide { align-items: flex-start; }

/* Card positions */
.drag-card[data-d="0"] {}
.drag-card[data-d="1"] { transform: translate(-30px, 24px) rotate(-1.5deg); }
.drag-card[data-d="2"] { transform: translate(38px, 42px) rotate(1.2deg); }
.drag-card[data-d="3"] { transform: translate(14px, 62px) rotate(0.4deg); }
.drag-card[data-d="4"] { transform: translate(-10px, 82px) rotate(-0.8deg); opacity: 0.9; }
.drag-card[data-d="5"] { transform: translate(50px, 14px) rotate(0.8deg); }
.drag-card[data-d="6"] {
  grid-column: 1 / -1;
  padding: var(--space-5) var(--space-5);
  min-height: 100px;
  transform: translate(-6px, 34px) rotate(2deg);
  z-index: 10;
}

@media (max-width: 900px) {
  .enemy-chaos { grid-template-columns: repeat(2, 1fr); gap: var(--space-3); }
  .drag-card[data-d="6"] { grid-column: 1 / -1; }
}
@media (max-width: 500px) {
  .enemy-chaos { grid-template-columns: 1fr; }
}

/* ═══════════════════════════════════════════════════════════
   PROOF — Mirofish Principle 3: flowing pipe
   ═══════════════════════════════════════════════════════════ */
.proof { padding: var(--space-10) 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.proof-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.proof-headline {
  font-size: clamp(48px, 6vw, 72px);
  font-weight: 300; line-height: 1.05; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-4); max-width: 50ch;
}
.proof-intro {
  font-size: 20px; font-weight: 400; color: var(--text-dim); max-width: 40ch; margin-bottom: var(--space-8);
}
.proof-pipe {
  position: relative;
  display: grid;
  grid-template-columns: 60px 1fr;
  gap: var(--space-6);
  margin-top: var(--space-8);
  align-items: start;
}
.pipe-conduit {
  position: absolute;
  top: 32px; bottom: 0;
  left: calc(50% + 32px);
  right: 0;
  pointer-events: none;
  z-index: 0;
}
.pipe-line {
  position: absolute; top: 0; bottom: 0;
  left: 50%; width: 1px;
  background: var(--border);
  transform: translateX(-50%);
}
.pipe-particle {
  position: absolute; top: 0; left: 50%;
  width: 6px; height: 6px;
  background: var(--signal);
  border-radius: 50%;
  transform: translateX(-50%);
  box-shadow: 0 0 12px rgba(32,247,130,0.4);
  animation: pipeParticle 4s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}
@keyframes pipeParticle {
  0% { top: 0; opacity: 0; }
  8% { opacity: 1; }
  92% { opacity: 1; }
  100% { top: calc(100% - 6px); opacity: 0; }
}
.pipe-step {
  position: relative; display: flex; gap: var(--space-5);
  align-items: flex-start; padding: var(--space-4) 0;
  z-index: 1;
}
.pipe-node {
  flex: 0 0 auto; width: 60px; height: 60px;
  border: 1px solid var(--border-strong); background: var(--bg);
  display: flex; align-items: center; justify-content: center;
  position: relative;
}
.pipe-node--active { border-color: var(--signal); background: var(--signal-dim); }
.pipe-num { font-size: 18px; font-weight: 600; letter-spacing: -0.02em; color: var(--text-dim); }
.pipe-node--active .pipe-num { color: var(--signal); }
.pipe-dot {
  position: absolute; bottom: -4px; right: -4px;
  width: 12px; height: 12px; border-radius: 50%;
  border: 1px solid var(--border-strong); background: var(--bg);
}
.pipe-dot--signal { background: var(--signal); border-color: var(--signal); }
.pipe-body { display: flex; flex-direction: column; gap: var(--space-1); padding-top: var(--space-1); }
.pipe-label { font-size: 16px; font-weight: 600; letter-spacing: -0.01em; color: var(--text); }
.pipe-desc {
  font-size: 13px; font-weight: 400; color: var(--text-dim); line-height: 1.5;
  letter-spacing: 0.01em; max-width: 32ch;
}
.pipe-step--complete .pipe-node { border-color: var(--signal); background: var(--signal-dim); }
.pipe-step--complete .pipe-num { color: var(--signal); }
.pipe-step--complete .pipe-dot { background: var(--signal); border-color: var(--signal); }
.human-bound {
  margin-top: var(--space-8);
  padding: var(--space-5) var(--space-6);
  border: 1px dashed var(--border-strong);
  display: flex; flex-direction: column; gap: var(--space-2);
}
.human-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--text-dim);
}
.human-desc { font-size: 18px; font-weight: 400; color: var(--text); line-height: 1.5; }

@media (max-width: 768px) {
  .proof-pipe { grid-template-columns: 48px 1fr; gap: var(--space-4); }
  .pipe-node { width: 48px; height: 48px; }
  .pipe-num { font-size: 14px; }
  .pipe-conduit { left: calc(50% + 24px); }
  .proof { padding: var(--space-8) 0; }
}
@media (max-width: 480px) {
  .proof-pipe { grid-template-columns: 1fr; }
  .pipe-step { flex-direction: column; align-items: center; text-align: center; }
  .pipe-node { width: 56px; height: 56px; }
  .pipe-body { align-items: center; }
  .pipe-desc { max-width: none; }
}

/* ═══════════════════════════════════════════════════════════
   HOW TWINTHOS WORKS
   ═══════════════════════════════════════════════════════════ */
.how { padding: var(--space-10) 0; }
.how-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.how-headline {
  font-size: clamp(40px, 5vw, 56px);
  font-weight: 300; line-height: 1.1; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-7); max-width: 65ch;
}
.how-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6);
  margin-top: var(--space-7); align-items: start;
}
.how-step {
  padding: var(--space-6);
  border: 1px solid var(--border);
  background: #0a0a0a;
  display: flex; gap: var(--space-4); align-items: flex-start;
}
.how-num {
  font-size: 40px; font-weight: 300; line-height: 1.0; letter-spacing: -0.03em;
  color: var(--text-dim); flex-shrink: 0;
}
.how-num.signal { color: var(--signal); }
.how-content { flex: 1; }
.how-label {
  font-size: 14px; font-weight: 600; letter-spacing: -0.01em;
  color: var(--text); margin-bottom: var(--space-3);
}
.how-desc {
  font-size: 15px; font-weight: 400; line-height: 1.5;
  letter-spacing: 0.01em; color: var(--text-dim);
}
@media (max-width: 768px) {
  .how-grid { grid-template-columns: 1fr; gap: var(--space-4); }
  .how { padding: var(--space-8) 0; }
}

/* ═══════════════════════════════════════════════════════════
   REDACTED EXAMPLE — Mirofish Principle 4
   ═══════════════════════════════════════════════════════════ */
.redacted { padding: var(--space-10) 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.redacted-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.redacted-headline {
  font-size: clamp(40px, 5vw, 56px);
  font-weight: 300; line-height: 1.1; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-5); max-width: 60ch;
}
.redacted-desc {
  font-size: 20px; font-weight: 400; color: var(--text-dim); max-width: 58ch;
  line-height: 1.6; margin-bottom: var(--space-7);
}
.redacted-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 0;
  margin-top: var(--space-7);
}
.redacted-item {
  padding: var(--space-6) var(--space-5);
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: #0a0a0a;
}
.redacted-item:nth-child(3n) { border-right: none; }
.redacted-item-label {
  display: flex; align-items: center; gap: var(--space-3);
  margin-bottom: var(--space-4);
}
.redacted-item-num {
  font-size: 14px; font-weight: 300; letter-spacing: -0.02em;
  color: var(--signal); font-variant-numeric: tabular-nums;
}
.redacted-item-title {
  font-size: 13px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--text-dim);
}
.redacted-item-body {
  font-size: 18px; font-weight: 300; line-height: 1.8; letter-spacing: -0.01em;
  color: var(--text);
}
.redacted-cta-row {
  margin-top: var(--space-7);
  display: flex; align-items: center; justify-content: space-between; gap: var(--space-5);
}
.redacted-cta-note { font-size: 13px; color: var(--text-faint); letter-spacing: 0.03em; }
@media (max-width: 768px) {
  .redacted-grid { grid-template-columns: 1fr; }
  .redacted-item { border-right: none; border-bottom: 1px solid var(--border); }
  .redacted-item:nth-child(3n) { border-right: 1px solid var(--border); }
  .redacted-item:last-child,
  .redacted-item:nth-last-child(2),
  .redacted-item:nth-last-child(3) { border-bottom: none; }
  .redacted { padding: var(--space-8) 0; }
}

/* ═══════════════════════════════════════════════════════════
   HUMAN ARCHITECT — Mirofish Principle 4
   ═══════════════════════════════════════════════════════════ */
.human-architect {
  padding: var(--space-10) 0;
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.human-grid {
  max-width: 1200px; margin: 0 auto; padding: 0 var(--space-8);
  display: grid; grid-template-columns: auto 1fr; gap: var(--space-8); align-items: center;
}
.human-mark { flex-shrink: 0; opacity: 0.92; }
.human-mark svg { width: 100%; height: auto; }
.human-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.human-headline {
  font-size: clamp(40px, 5vw, 56px);
  font-weight: 300; line-height: 1.1; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-5); max-width: 55ch;
}
.human-sub {
  font-size: 20px; font-weight: 400; color: var(--text-dim); line-height: 1.6; max-width: 50ch;
}
@media (max-width: 768px) {
  .human-grid { grid-template-columns: 1fr; gap: var(--space-5); text-align: center; }
  .human-mark { order: -1; }
  .human-headline { max-width: 100%; }
  .human-sub { max-width: 48ch; margin: 0 auto; }
  .human-architect { padding: var(--space-8) 0; }
}

/* ═══════════════════════════════════════════════════════════
   OFFER — Mirofish Principle 4
   ═══════════════════════════════════════════════════════════ */
.offer {
  padding: var(--space-10) var(--space-8);
  text-align: center;
  border-top: 1px solid var(--border);
}
.offer-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--text-dim); margin-bottom: var(--space-5);
}
.offer-price-block {
  display: flex; flex-direction: column; align-items: center; gap: var(--space-2);
  margin-bottom: var(--space-7);
}
.offer-price {
  font-size: clamp(64px, 10vw, 110px);
  font-weight: 300; line-height: 1.0; letter-spacing: -0.035em;
  color: var(--text);
}
.offer-price-unit {
  font-size: 22px; font-weight: 500; color: var(--text-dim); letter-spacing: 0.02em;
}
.offer-price-note {
  font-size: 13px; color: var(--text-faint); letter-spacing: 0.06em;
  text-transform: uppercase; margin-top: var(--space-1);
}
.offer-desc {
  font-size: 20px; font-weight: 400; color: var(--text-dim); max-width: 46ch;
  margin: 0 auto var(--space-8) auto; line-height: 1.6;
}
.offer-list {
  display: flex; flex-direction: column; align-items: center; gap: var(--space-3);
  max-width: 56ch; margin: 0 auto var(--space-8) auto;
}
.offer-list-item {
  display: flex; align-items: center; gap: var(--space-3);
  font-size: 20px; font-weight: 400; color: var(--text);
  flex-wrap: wrap; justify-content: center;
}
.offer-list-sep {
  width: 4px; height: 4px; border-radius: 50%;
  background: var(--border-strong); flex-shrink: 0;
}
.offer-cta-row {
  display: flex; flex-direction: column; align-items: center; gap: var(--space-4);
}
.offer-cta {
  font-size: 15px; font-weight: 600; letter-spacing: -0.01em;
  color: var(--bg); background: var(--signal);
  padding: 18px 32px;
