}
.offer-cta:hover { background: #1ae075; color: var(--bg); }
.offer-cta-sub {
  font-size: 13px; color: var(--text-faint); letter-spacing: 0.03em;
}
@media (max-width: 600px) {
  .offer { padding: var(--space-8) var(--space-4); }
  .offer-list-item { font-size: 16px; }
}

/* ═══════════════════════════════════════════════════════════
   FINAL CTA — Mirofish Principle 6
   ═══════════════════════════════════════════════════════════ */
.final-cta {
  padding: var(--space-10) 0;
  text-align: center;
  background: #0a0a0a;
  border-top: 1px solid var(--border);
}
.final-cta-label {
  font-size: 12px; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase;
