}
.final-cta-headline {
  font-size: clamp(40px, 5vw, 56px);
  font-weight: 300; line-height: 1.1; letter-spacing: -0.025em;
  color: var(--text); margin-bottom: var(--space-5);
  max-width: 60ch; margin-left: auto; margin-right: auto;
}
.final-cta-sub {
  font-size: 20px; font-weight: 400; color: var(--text-dim); max-width: 42ch;
  margin: 0 auto var(--space-7) auto; line-height: 1.6;
}
.final-cta-actions {
  display: flex; flex-direction: column; align-items: center; gap: var(--space-4);
}
.final-cta-btn {
  font-size: 16px; font-weight: 600; letter-spacing: -0.01em;
  color: var(--bg); background: var(--signal);
  padding: 18px 32px;
  transition: background var(--speed), transform var(--speed);
}
.final-cta-btn:hover { background: #1ae075; color: var(--bg); }
.final-cta-secondary {
  font-size: 14px; color: var(--text-faint);
}
@media (max-width: 600px) {
  .final-cta { padding: var(--space-8) 0; }
  .final-cta-headline { font-size: 32px; }
}

/* ═══════════════════════════════════════════════════════════
   FOOTER
   ═══════════════════════════════════════════════════════════ */
.footer {
  padding: var(--space-6) 0;
  border-top: 1px solid var(--border);
  background: var(--bg);
}
.footer-inner {
  max-width: var(--container); margin: 0 auto; padding: 0 var(--space-8);
  display: flex; align-items: center; justify-content: space-between; gap: var(--space-5);
}
.footer-copy {
  font-size: 13px; color: var(--text-faint); letter-spacing: -0.01em;
}
.footer-links { display: flex; gap: var(--space-5); }
.footer-link {
  font-size: 13px; color: var(--text-dim); transition: color var(--speed);
}
.footer-link:hover { color: var(--text); }
@media (max-width: 600px) {
  .footer-inner { flex-direction: column; text-align: center; gap: var(--space-4); }
  .footer { padding: var(--space-5) 0; }
}

/* ═══════════════════════════════════════════════════════════
   REVEAL ANIMATIONS
   ═══════════════════════════════════════════════════════════ */
.reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity var(--speed-slower) var(--ease), transform var(--speed-slower) var(--ease);
}
.reveal-fast {
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 350ms var(--ease), transform 350ms var(--ease);
}
.reveal.in { opacity: 1; transform: translateY(0); }
.reveal-fast.in { opacity: 1; transform: translateY(0); }

[data-stagger-child] { opacity: 0; }
[data-stagger-child].in { opacity: 1; }

@media (prefers-reduced-motion: reduce) {
  .reveal, .reveal-fast, [data-stagger-child] {
    opacity: 1; transform: none; transition: none;
  }
  .pipe-particle { animation: none; opacity: 0.4; }
}
</style>
</head>
