<main id="main">

<!-- ═══════════════════════ 01 HERO ═══════════════════════ -->
<section class="hero" id="hero">
  <div class="hero-inner">
    <div class="hero-content">
      <p class="hero-label">Managed operations</p>
      <h1 class="hero-headline" id="heroHeadline">
        <span class="word">Your</span>
        <span class="word">team</span>
        <span class="word">shouldn't</span>
        <span class="word">spend</span>
        <span class="word">their</span>
        <span class="word">day</span>
        <span class="word">on</span>
        <span class="word">work</span>
        <span class="word">a</span>
        <span class="word">machine</span>
        <span class="word">could</span>
        <span class="word">do</span>
        <span class="word">.</span>
      </h1>
      <p class="hero-body">
        Twinthos removes the operational glue work — chasing updates, updating records, following up — so your operation runs without constant attention.
      </p>
      <a href="#offer" class="hero-cta">Assess your operation</a>
      <p class="hero-secondary">No software to buy. No dashboard to learn.</p>
