<script>
(function () {
  'use strict';
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // NAV scroll state
  var nav = document.getElementById('nav');
  var ticking = false;
  function navBg() {
    nav.style.background = window.scrollY > 20 ? 'rgba(0,0,0,0.96)' : 'rgba(0,0,0,0.7)';
    nav.classList.toggle('scrolled', window.scrollY > 20);
    ticking = false;
  }
  window.addEventListener('scroll', function () {
    if (!ticking) { ticking = true; requestAnimationFrame(navBg); }
  }, { passive: true });
  navBg();

  // Mobile burger
  var burger = document.getElementById('navBurger');
  var links = document.getElementById('navLinks');
  if (burger && links) {
    burger.addEventListener('click', function () {
      var open = burger.getAttribute('aria-expanded') === 'true';
      burger.setAttribute('aria-expanded', open ? 'false' : 'true');
      links.style.display = open ? 'none' : 'flex';
      links.style.flexDirection = 'column';
      links.style.position = 'absolute';
      links.style.top = '56px';
      links.style.right = 'var(--space-4)';
      links.style.background = 'rgba(0,0,0,0.96)';
      links.style.padding = 'var(--space-5)';
      links.style.gap = 'var(--space-4)';
      links.style.border = '1px solid var(--border-strong)';
      links.style.borderRadius = '0';
    });
    links.addEventListener('click', function (e) {
      if (e.target.tagName === 'A') {
        links.style.display = 'none';
        burger.setAttribute('aria-expanded', 'false');
      }
    });
  }

  // HERO WORD-BY-WORD REVEAL
  if (!reduceMotion) {
    var heroHead = document.getElementById('heroHeadline');
    if (heroHead && heroHead.children.length > 0) {
      var words = heroHead.querySelectorAll('.word');
      words.forEach(function (w, i) {
        w.style.transitionDelay = (i * 55) + 'ms';
        requestAnimationFrame(function () {
          requestAnimationFrame(function () {
            w.classList.add('in');
          });
        });
      });
    }
  }

  // SCROLL REVEAL
  if (!reduceMotion && 'IntersectionObserver' in window) {
    var reveals = document.querySelectorAll('.reveal, .reveal-fast, [data-stagger-child]');
    if (reveals.length) {
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            var el = entry.target;
            var delay = parseInt(el.getAttribute('data-delay') || el.getAttribute('data-stagger-child') * 60 || 0);
            setTimeout(function () { el.classList.add('in'); }, delay);
            observer.unobserve(el);
          }
        });
      }, { threshold: 0.08, rootMargin: '0px 0px -4% 0px' });
      reveals.forEach(function (el) { observer.observe(el); });
    }
  }

  // CTA HOVER
  if (!reduceMotion) {
    var btns = document.querySelectorAll('.hero-cta, .offer-cta, .final-cta-btn, .nav-cta');
    btns.forEach(function (b) {
      b.addEventListener('pointerdown', function () { b.style.transform = 'scale(0.97)'; });
      b.addEventListener('pointerup', function () { b.style.transform = ''; });
      b.addEventListener('pointerleave', function () { b.style.transform = ''; });
    });
  }

  // SMOOTH SCROLL
  document.querySelectorAll('a[href^="#"]').forEach(function (a) {
    a.addEventListener('click', function (e) {
      var id = a.getAttribute('href').slice(1);
      if (!id) return;
      var target = document.getElementById(id);
      if (!target) return;
      e.preventDefault();
      var y = target.getBoundingClientRect().top + window.scrollY - 80;
      window.scrollTo({ top: y, behavior: reduceMotion ? 'auto' : 'smooth' });
    });
  });
})();
</script>

