84|  background: var(--bg);
85|  color: var(--text);
86|  overflow-x: hidden;
87|  min-height: 100vh;
88|}
89|a { color: inherit; text-decoration: none; }
90|button { font: inherit; cursor: pointer; border: none; background: none; }
91|img, svg { display: block; max-width: 100%; }
92|ul, ol { list-style: none; }
