99|  position: absolute; top: -100%; left: var(--space-4); z-index: 200;
100|  font-size: 13px; padding: 8px 16px; background: var(--text); color: var(--bg);
101|  transition: top var(--speed) var(--ease);
102|}
103|.skip-link:focus { top: var(--space-3); }
